+const navToggle = document.querySelector(".nav-toggle");
+const primaryNav = document.querySelector(".primary-nav");
+const navLinks = document.querySelectorAll(".primary-nav a");
+const cartLink = document.querySelector(".cart-link");
+const cartCount = document.querySelector(".cart-count");
+const addToCartButtons = document.querySelectorAll(".add-to-cart");
+const statusMessage = document.querySelector(".status-message");
+const newsletterForm = document.querySelector(".newsletter-form");
+
+let bagCount = 0;
+let statusTimer;
+
+function announce(message) {
+  window.clearTimeout(statusTimer);
+  statusMessage.textContent = message;
+  statusMessage.classList.add("is-visible");
+
+  statusTimer = window.setTimeout(() => {
+    statusMessage.classList.remove("is-visible");
+  }, 3200);
+}
+
+function closeNavigation() {
+  navToggle.setAttribute("aria-expanded", "false");
+  primaryNav.classList.remove("is-open");
+  document.body.classList.remove("nav-open");
+}
+
+navToggle.addEventListener("click", () => {
+  const isExpanded = navToggle.getAttribute("aria-expanded") === "true";
+  navToggle.setAttribute("aria-expanded", String(!isExpanded));
+  primaryNav.classList.toggle("is-open", !isExpanded);
+  document.body.classList.toggle("nav-open", !isExpanded);
+});
+
+navLinks.forEach((link) => {
+  link.addEventListener("click", closeNavigation);
+});
+
+document.addEventListener("keydown", (event) => {
+  if (event.key === "Escape" && navToggle.getAttribute("aria-expanded") === "true") {
+    closeNavigation();
+    navToggle.focus();
+  }
+});
+
+addToCartButtons.forEach((button) => {
+  button.addEventListener("click", () => {
+    const productName = button.dataset.product;
+    bagCount += 1;
+    cartCount.textContent = String(bagCount);
+    cartLink.setAttribute("aria-label", `View shopping bag, ${bagCount} ${bagCount === 1 ? "item" : "items"}`);
+    announce(`${productName} added to your bag. Bag now has ${bagCount} ${bagCount === 1 ? "item" : "items"}.`);
+  });
+});
+
+newsletterForm.addEventListener("submit", (event) => {
+  event.preventDefault();
+  const emailInput = newsletterForm.querySelector("#email");
+
+  if (!emailInput.checkValidity()) {
+    emailInput.reportValidity();
+    return;
+  }
+
+  announce("Thanks for joining North & Finch Membership. Check your inbox for a welcome offer.");
+  newsletterForm.reset();
+});
