  .primary-nav a {
    width: 100%;
  }

  .cart-link {
    grid-column: 3;
    grid-row: 1;
  }

  .hero-grid,
  .editorial-grid,
  .newsletter-panel {
    grid-template-columns: 1fr;
  }

  .product-grid,
  .deals-grid {
    grid-template-columns: 1fr;
  }

  .section-heading {
    align-items: flex-start;
    flex-direction: column;
  }
}

@media (max-width: 520px) {
