.primary-nav a,
.cart-link {
  display: inline-flex;
  align-items: center;
  min-height: 44px;
  border-radius: 999px;
  color: var(--color-text);
  font-weight: 700;
  text-decoration: none;
}

.primary-nav a {
  padding: 0.7rem 1rem;
}

.primary-nav a:hover,
.cart-link:hover {
  background: var(--color-surface-warm);
}

.cart-link {
  gap: 0.5rem;
  justify-self: end;
  padding: 0.65rem 0.85rem;
}

.cart-count {
  display: grid;
  min-width: 1.7rem;
  height: 1.7rem;
  place-items: center;
  border-radius: 999px;
  background: var(--color-primary);
  color: var(--color-primary-text);
  font-size: 0.85rem;
}

.nav-toggle {
  display: none;
  min-height: 44px;
  align-items: center;
  gap: 0.55rem;
  border: 1px solid var(--color-border);
  border-radius: 999px;
  background: var(--color-surface);
  color: var(--color-text);
  padding: 0.65rem 0.85rem;
  font-weight: 800;
}

.nav-toggle-icon,
.nav-toggle-icon::before,
.nav-toggle-icon::after {
  display: block;
  width: 1.1rem;
  height: 2px;
  border-radius: 999px;
  background: currentColor;
}

.nav-toggle-icon {
  position: relative;
}

.nav-toggle-icon::before,
.nav-toggle-icon::after {
  content: "";
  position: absolute;
  left: 0;
}

.nav-toggle-icon::before {
  top: -0.36rem;
}

.nav-toggle-icon::after {
  top: 0.36rem;
}

.hero {
  padding: clamp(3rem, 8vw, 7rem) 0 4rem;
}

.hero-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(280px, 0.75fr);
  align-items: center;
  gap: clamp(2rem, 6vw, 5rem);
}

.eyebrow,
.product-kicker,
.deal-label,
.article-meta {
