  min-height: 360px;
  background:
    linear-gradient(135deg, #e7d7bf 0%, #d6e0cf 52%, #ebe4d7 100%);
}

.orb {
  position: absolute;
  display: block;
  border-radius: 45% 55% 48% 52%;
  border: 1px solid color-mix(in srgb, var(--color-text) 18%, transparent);
