  left: 13%;
  top: 17%;
  background: #f8f1e8;
}

.orb-two {
  width: 38%;
  aspect-ratio: 1;
  right: 11%;
  top: 29%;
  background: #d18246;
}

.orb-three {
  width: 32%;
  aspect-ratio: 1;
  left: 28%;
  bottom: 11%;
  background: #244b3d;
}

.hero-offer {
  padding: 1.5rem;
}

.offer-label {
  display: inline-flex;
  margin-bottom: 0.85rem;
  border-radius: 999px;
  background: var(--color-surface-warm);
  color: var(--color-primary);
  padding: 0.35rem 0.7rem;
  font-size: 0.8rem;
  font-weight: 800;
}

.hero-offer strong {
  display: block;
  font-size: 1.45rem;
  line-height: 1.15;
  letter-spacing: -0.04em;
}

.hero-offer p {
  margin: 0.65rem 0 0;
  color: var(--color-muted-text);
}

.hero-offer span:last-child {
  color: var(--color-text);
