}

.product-media-ink {
  background: radial-gradient(circle at 68% 42%, #d6e0cf 0 20%, transparent 21%), #233f4c;
}

.product-content {
  display: grid;
  gap: 0.5rem;
  padding: 1.25rem;
}

.product-description,
.deal-card p,
.story-card p,
.editorial-copy p,
.site-footer p {
  color: var(--color-muted-text);
}

.product-meta {
  justify-content: space-between;
  gap: 1rem;
  margin: 0.4rem 0 0.7rem;
}

.price {
  font-size: 1.25rem;
  font-weight: 800;
}

.rating {
