  font-size: 0.92rem;
  font-weight: 700;
}

.add-to-cart {
  width: 100%;
}

.deals-section {
  background: var(--color-surface-warm);
}

.deals-grid {
  display: grid;
  grid-template-columns: 1.35fr 1fr 1fr;
  gap: 1rem;
}

.deal-card {
