}

.newsletter-panel {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(300px, 0.8fr);
  align-items: end;
  gap: 1.5rem;
  padding: clamp(1.25rem, 4vw, 2.2rem);
  background:
