  *::after {
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
  }
}

@media (max-width: 860px) {
  .header-inner {
    grid-template-columns: auto auto auto;
    justify-content: space-between;
  }

  .nav-toggle {
    display: inline-flex;
    grid-column: 2;
    grid-row: 1;
  }

  .primary-nav {
    position: fixed;
    inset: 74px 1rem auto;
    display: none;
    justify-self: stretch;
    border: 1px solid var(--color-border);
    border-radius: var(--radius-md);
    background: var(--color-surface);
    padding: 0.75rem;
    box-shadow: 0 20px 50px var(--color-shadow);
  }

  .primary-nav.is-open {
    display: block;
  }

  .primary-nav ul {
    display: grid;
    gap: 0.2rem;
  }

  .primary-nav a {
    width: 100%;
  }

  .cart-link {
    grid-column: 3;
    grid-row: 1;
  }

  .hero-grid,
  .editorial-grid,
  .newsletter-panel {
    grid-template-columns: 1fr;
  }

  .product-grid,
  .deals-grid {
    grid-template-columns: 1fr;
  }

  .section-heading {
    align-items: flex-start;
    flex-direction: column;
  }
}

@media (max-width: 520px) {
  .container {
    width: min(100% - 1rem, var(--max-width));
  }

  .header-inner {
    gap: 0.5rem;
    min-height: 68px;
  }

  .brand span:last-child,
  .nav-toggle-text,
  .cart-link span:first-child {
    clip: rect(0 0 0 0);
    clip-path: inset(50%);
    height: 1px;
    overflow: hidden;
    position: absolute;
    white-space: nowrap;
    width: 1px;
  }

  .primary-nav {
    inset: 68px 0.5rem auto;
  }

  .hero {
    padding-top: 2.5rem;
  }

  .hero-card {
    border-radius: var(--radius-md);
  }

  .hero-art {
    min-height: 250px;
  }

  .button,
  .hero-actions,
  .newsletter-form .button {
    width: 100%;
  }
}

@media (forced-colors: active) {
  .site-header,
  .product-card,
  .deal-card,
  .story-card,
  .editorial-feature,
  .newsletter-panel,
  .hero-card,
  .primary-nav,
  .field input,
  .status-message {
    border: 1px solid CanvasText;
    box-shadow: none;
  }

  .button,
  .add-to-cart,
  .nav-toggle,
  .cart-count,
  .brand-mark {
    border: 1px solid ButtonBorder;
  }

  .hero-art,
  .product-media,
  .editorial-image {
    border-bottom: 1px solid CanvasText;
  }
}
