  background: var(--color-surface);
  color: var(--color-text);
}

.button-secondary:hover {
  background: var(--color-surface-warm);
  color: var(--color-text);
}

.button-light {
  background: var(--color-primary-text);
  color: var(--color-primary);
}

.button-light:hover {
  background: var(--color-surface-warm);
  color: var(--color-primary-hover);
}

.hero-card {
