.orb-two {
  width: 38%;
  aspect-ratio: 1;
  right: 11%;
  top: 29%;
  background: #d18246;
}

.orb-three {
  width: 32%;
  aspect-ratio: 1;
  left: 28%;
  bottom: 11%;
  background: #244b3d;
}

.hero-offer {
