}

.product-card {
  overflow: hidden;
  height: 100%;
  box-shadow: 0 16px 38px color-mix(in srgb, var(--color-shadow) 58%, transparent);
}

.product-media {
  display: grid;
  min-height: 230px;
  place-items: end start;
  padding: 1.2rem;
}

.product-media span {
  color: var(--color-primary-text);
