}

.product-media-sage {
  background: radial-gradient(circle at 70% 35%, #f8f1e8 0 20%, transparent 21%), #6f7d5c;
}

.product-media-clay {
  background: radial-gradient(circle at 30% 35%, #f1dac4 0 24%, transparent 25%), #a6532f;
}

.product-media-ink {
  background: radial-gradient(circle at 68% 42%, #d6e0cf 0 20%, transparent 21%), #233f4c;
}

.product-content {
