node <<'NODE'
const path = require('path');
const { chromium } = require('/tmp/north-finch-a11y/node_modules/playwright');
const axe = require('/tmp/north-finch-a11y/node_modules/axe-core');

async function runViewport(viewport) {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport });
  await page.goto('file://' + path.resolve('index.html'), { waitUntil: 'load' });
  await page.addScriptTag({ content: axe.source });
  const result = await page.evaluate(async () => window.axe.run());
  await browser.close();
  return result.violations;
}

(async () => {
  const viewports = [{ width: 1366, height: 900 }, { width: 360, height: 800 }];
  const all = [];
  for (const viewport of viewports) {
    const violations = await runViewport(viewport);
    for (const violation of violations) {
      all.push({ viewport, violation });
    }
  }
  const wcag = all.filter(({ violation }) => !violation.tags.includes('best-practice'));
  const bp = all.filter(({ violation }) => violation.tags.includes('best-practice'));
  console.log(JSON.stringify({
    wcag: wcag.map(({ viewport, violation }) => ({ viewport, id: violation.id, impact: violation.impact, targets: violation.nodes.map((n) => n.target) })),
    bp: bp.map(({ viewport, violation }) => ({ viewport, id: violation.id, impact: violation.impact, targets: violation.nodes.map((n) => n.target) }))
  }, null, 2));
  process.exit(wcag.length ? 1 : 0);
})().catch((error) => {
  console.error(error.message);
  process.exit(2);
});
