  try { return require(name); } catch { return require(`/tmp/north-finch-a11y/node_modules/${name}`); }
}
const { chromium } = requirePkg('playwright');
const axe = requirePkg('axe-core');

async function runAxe(page, label) {
  const result = await page.evaluate(async () => window.axe.run(document, {
    runOnly: { type: 'tag', values: ['wcag2a', 'wcag2aa', 'wcag21a', 'wcag21aa', 'wcag22aa', 'best-practice'] }
  }));
  return result.violations.map((v) => ({ label, id: v.id, impact: v.impact, tags: v.tags, targets: v.nodes.map((n) => n.target) }));
}

(async () => {
  const browser = await chromium.launch();
  const all = [];
  const desktop = await browser.newPage({ viewport: { width: 1366, height: 900 } });
  await desktop.goto('file://' + path.resolve('index.html'), { waitUntil: 'load' });
  await desktop.addScriptTag({ content: axe.source });
  all.push(...await runAxe(desktop, 'desktop'));
  await desktop.click('button.add-to-cart');
  all.push(...await runAxe(desktop, 'desktop-after-add-to-bag'));
  await desktop.close();
  const mobile = await browser.newPage({ viewport: { width: 320, height: 800 } });
  await mobile.goto('file://' + path.resolve('index.html'), { waitUntil: 'load' });
  await mobile.addScriptTag({ content: axe.source });
  all.push(...await runAxe(mobile, 'mobile'));
  await mobile.click('.nav-toggle');
  all.push(...await runAxe(mobile, 'mobile-nav-open'));
  await mobile.close();
  await browser.close();
  const wcag = all.filter((v) => !v.tags.includes('best-practice'));
  console.log(JSON.stringify({
    wcag: wcag.map(({ label, id, impact, targets }) => ({ label, id, impact, targets })),
    bestPractice: all.filter((v) => v.tags.includes('best-practice')).map(({ label, id, impact, targets }) => ({ label, id, impact, targets }))
  }, null, 2));
  process.exit(wcag.length ? 1 : 0);
})().catch((error) => { console.error(error); process.exit(2); });
